import * as mocks from '../constants';

interface IDataService {
    getAll<T>(collection: string, userId?: string, isAdmin?: boolean): Promise<T[]>;
    save<T extends { id: string | number }>(collection: string, item: T): Promise<T>;
    saveAll<T extends { id: string | number }>(collection: string, items: T[]): Promise<T[]>;
    delete(collection: string, id: string | number): Promise<boolean>;
}

const STORAGE_PREFIX = 'orner_local_db_';

class LocalDataService implements IDataService {

    private getLocal<T>(collection: string): T[] {
        const key = STORAGE_PREFIX + collection;
        const stored = localStorage.getItem(key);

        if (stored) {
            try {
                const parsed = JSON.parse(stored);
                return Array.isArray(parsed) ? parsed : [];
            } catch (e) {
                console.error(`[DB LOCAL] Erro ao ler storage: ${collection}`, e);
                return [];
            }
        }

        const initialClassifications = [
            { id: 'RECEITA_VENDA', name: 'Receita bruta (vendas)', type: 'receita' },
            { id: 'OUTRA_RECEITA', name: 'Outras receitas', type: 'receita' },
            { id: 'DEDUCAO_RECEITA', name: 'Deduções de receita', type: 'receita' },
            { id: 'CUSTO_VENDA', name: 'Custo mercadoria/serviço', type: 'despesa' },
            { id: 'DESPESA_VARIAVEL', name: 'Despesa variável (taxas/fretes)', type: 'despesa' },
            { id: 'DESPESA_OPERACIONAL', name: 'Despesa operacional (fixa)', type: 'despesa' },
            { id: 'OUTRA_DESPESA', name: 'Outras despesas', type: 'despesa' }
        ];

        const mockKeyMap: Record<string, any> = {
            'system_users': mocks.MOCK_USERS || [],
            'system_profiles': mocks.MOCK_PROFILES || [],
            'financial_transactions': mocks.MOCK_FINANCIAL_TRANSACTIONS || [],
            'financial_categories': mocks.FINANCIAL_CATEGORIES || [],
            'financial_classifications': initialClassifications,
            'stock_items': mocks.MOCK_STOCK_ITEMS || [],
            'orcamentos': [],
            'sales_summary': mocks.MOCK_SALES_SUMMARY || [],
            'stock_movements': mocks.MOCK_STOCK_MOVEMENTS || [],
            'purchase_requests': mocks.MOCK_PURCHASE_REQUESTS || [],
            'checklist_checkin': [],
            'checklist_checkout': [],
            'checklist_manutencao': [],
            'expense_reports': [],
            'credit_cards': [],
            'financial_groups': []
        };

        const initialData = mockKeyMap[collection] || [];
        this.setLocal(collection, initialData);
        return initialData;
    }

    private setLocal<T>(collection: string, data: T[]) {
        try {
            localStorage.setItem(STORAGE_PREFIX + collection, JSON.stringify(data));
        } catch (e) {
            console.error("Falha ao salvar no LocalStorage", e);
        }
    }

    async getAll<T>(collection: string, userId?: string, isAdmin?: boolean): Promise<T[]> {
        const data = this.getLocal<T>(collection);
        return Array.isArray(data) ? data : [];
    }

    async save<T extends { id: string | number }>(collection: string, item: T): Promise<T> {
        const list = this.getLocal<any>(collection);
        const itemToSave = { ...item };

        if (!itemToSave.id) {
            itemToSave.id = `loc-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
        }

        const index = list.findIndex((i: any) => String(i?.id) === String(itemToSave.id));
        if (index > -1) list[index] = itemToSave;
        else list.push(itemToSave);

        this.setLocal(collection, list);
        return itemToSave as T;
    }

    async saveAll<T extends { id: string | number }>(collection: string, items: T[]): Promise<T[]> {
        const list = this.getLocal<any>(collection);
        const processedItems = items.map(item => {
            const itemToSave = { ...item };
            if (!itemToSave.id) {
                itemToSave.id = `loc-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
            }
            return itemToSave;
        });

        processedItems.forEach(itemToSave => {
            const index = list.findIndex((i: any) => String(i?.id) === String(itemToSave.id));
            if (index > -1) list[index] = itemToSave;
            else list.push(itemToSave);
        });

        this.setLocal(collection, list);
        return processedItems as T[];
    }

    async delete(collection: string, id: string | number): Promise<boolean> {
        const list = this.getLocal<any>(collection);
        const filtered = list.filter((i: any) => String(i?.id) !== String(id));
        this.setLocal(collection, filtered);
        return true;
    }

    resetDatabase() {
        Object.keys(localStorage).forEach(key => {
            if (key.startsWith(STORAGE_PREFIX)) {
                localStorage.removeItem(key);
            }
        });
        window.location.reload();
    }
}

export const dataService = new LocalDataService();

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import DashboardPage from './pages/DashboardPage';
import OrcamentoPage from './pages/OrcamentoPage';
import FinanceiroPage from './pages/FinanceiroPage';
import RelatoriosPage from './pages/RelatoriosPage';
import NovoOrcamentoPage from './pages/NovoOrcamentoPage';
import ResumoVendasPage from './pages/ResumoVendasPage';
import EstoquePage from './pages/EstoquePage';
import CheckListPage from './pages/CheckListPage';
import UsuariosPage from './pages/UsuariosPage';
import { LockClosedIcon, ExclamationTriangleIcon } from './assets/icons';
import type { Page, SavedOrcamento, ExpenseReport, User, UserProfile } from './types';
import { dataService } from './services/dataService';
import { authService } from './services/authService';
import { MOCK_USERS } from './constants';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('DASHBOARD');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [editingOrcamento, setEditingOrcamento] = useState<SavedOrcamento | null>(null);
  const [editingReport, setEditingReport] = useState<ExpenseReport | null>(null);

  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [userPermissions, setUserPermissions] = useState<string[]>([]);
  const [isUserInitialized, setIsUserInitialized] = useState(false);
  const [hasError, setHasError] = useState(false);

  useEffect(() => {
    if (currentUser?.darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [currentUser?.darkMode]);

  const fetchPermissions = async (profileId: string) => {
    try {
      const profiles = await dataService.getAll<UserProfile>('system_profiles');
      const profile = Array.isArray(profiles) ? profiles.find(p => String(p.id) === String(profileId)) : null;
      if (profile) {
        setUserPermissions(profile.permissions || []);
      } else if (profileId === '001') {
          setUserPermissions(['ALL']); 
      }
    } catch (e) {
      console.error("Erro permissões:", e);
    }
  };

  useEffect(() => {
    try {
        const session = authService.getSession();
        if (session && session.id) {
            setCurrentUser(session);
            fetchPermissions(session.profileId);
        } else {
            const defaultAdmin = MOCK_USERS[0];
            setCurrentUser(defaultAdmin);
            fetchPermissions(defaultAdmin.profileId);
            authService.saveSession(defaultAdmin);
        }
    } catch (e) {
        console.error("Erro na inicialização da sessão:", e);
        setHasError(true);
    } finally {
        setIsUserInitialized(true);
    }
  }, []);

  const handleLogout = () => {
      authService.logout();
      window.location.reload();
  };

  const handleSetCurrentPage = (page: Page) => {
    if (page !== 'NOVO_ORCAMENTO') setEditingOrcamento(null);
    if (page !== 'RELATORIOS_NOVO') setEditingReport(null);

    // Tratamento para não cair em tela branca se clicar no ID de um menu pai
    const skipPages = ['ORCAMENTO_MENU', 'FINANCEIRO_MENU', 'RELATORIOS_MENU', 'OPERACIONAL_MENU', 'USUARIOS_MENU'];
    if (skipPages.includes(page)) return;

    setCurrentPage(page);
  }

  const renderPage = () => {
    if (!currentUser) return null;

    if (!currentUser.active) {
        return (
            <div className="flex flex-col items-center justify-center h-full space-y-6 text-center px-4">
                <div className="p-6 bg-red-100 rounded-full text-red-600 shadow-xl">
                    <LockClosedIcon className="w-20 h-20" />
                </div>
                <h2 className="text-3xl font-black text-gray-900 dark:text-white">Acesso bloqueado</h2>
                <button onClick={handleLogout} className="text-xs text-indigo-600 font-bold hover:underline">Sair</button>
            </div>
        );
    }

    try {
        switch (currentPage) {
          case 'DASHBOARD':
            return <DashboardPage />;
          case 'ORCAMENTO':
            return <OrcamentoPage setCurrentPage={handleSetCurrentPage} onEdit={(orc) => { setEditingOrcamento(orc); setCurrentPage('NOVO_ORCAMENTO'); }} currentUser={currentUser} />;
          case 'NOVO_ORCAMENTO':
            return <NovoOrcamentoPage setCurrentPage={handleSetCurrentPage} orcamentoToEdit={editingOrcamento} clearEditingOrcamento={() => setEditingOrcamento(null)} currentUser={currentUser} />;
          case 'RESUMO_VENDAS':
            return <ResumoVendasPage currentUser={currentUser} />;
          case 'FINANCEIRO_VISAO_GERAL':
            return <FinanceiroPage view="dashboard" currentUser={currentUser} />;
          case 'FINANCEIRO_A_RECEBER':
            return <FinanceiroPage view="aReceber" currentUser={currentUser} />;
          case 'FINANCEIRO_A_PAGAR':
            return <FinanceiroPage view="aPagar" currentUser={currentUser} />;
          case 'FINANCEIRO_DRE':
            return <FinanceiroPage view="dre" currentUser={currentUser} />;
          case 'FINANCEIRO_CATEGORIAS':
            return <FinanceiroPage view="categorias" currentUser={currentUser} />;
          case 'ESTOQUE_VISAO_GERAL':
            return <EstoquePage view="visao_geral" setCurrentPage={handleSetCurrentPage} currentUser={currentUser} />;
          case 'ESTOQUE_COMPRAS':
            return <EstoquePage view="compras" setCurrentPage={handleSetCurrentPage} currentUser={currentUser} />;
          case 'ESTOQUE_NOVO_PRODUTO':
            return <EstoquePage view="cadastro" setCurrentPage={handleSetCurrentPage} currentUser={currentUser} />;
          case 'CHECKLIST_CHECKIN':
            return <CheckListPage view="checkin" currentUser={currentUser} />;
          case 'CHECKLIST_CHECKOUT':
            return <CheckListPage view="checkout" currentUser={currentUser} />;
          case 'CHECKLIST_MANUTENCAO':
            return <CheckListPage view="manutencao" currentUser={currentUser} />;
          case 'RELATORIOS_VISAO_GERAL':
            return <RelatoriosPage view="analise" currentUser={currentUser} />;
          case 'RELATORIOS_STATUS':
            return <RelatoriosPage view="status" onEditReport={(rep) => { setEditingReport(rep); setCurrentPage('RELATORIOS_NOVO'); }} currentUser={currentUser} />;
          case 'RELATORIOS_HISTORICO':
            return <RelatoriosPage view="historico" onEditReport={(rep) => { setEditingReport(rep); setCurrentPage('RELATORIOS_NOVO'); }} currentUser={currentUser} />;
          case 'RELATORIOS_CONFIG':
            return <RelatoriosPage view="config" currentUser={currentUser} />;
          case 'RELATORIOS_NOVO':
            return <RelatoriosPage view="reembolso" reportToEdit={editingReport} onSave={() => setCurrentPage('RELATORIOS_STATUS')} currentUser={currentUser} />;
          case 'USUARIOS_GESTAO':
            return <UsuariosPage view="gestao" currentUser={currentUser} />;
          case 'USUARIOS_PERFIL':
            return <UsuariosPage view="perfil" currentUser={currentUser} />;
          default:
            return <DashboardPage />;
        }
    } catch (e) {
        console.error("Erro ao renderizar página:", e);
        return (
            <div className="p-8 text-center bg-red-50 rounded-2xl border border-red-100">
                <ExclamationTriangleIcon className="w-12 h-12 text-red-500 mx-auto mb-4" />
                <h3 className="text-lg font-bold text-red-800">Ops! Ocorreu um erro nesta tela.</h3>
                <p className="text-sm text-red-600 mb-4">Tente recarregar ou voltar para o início.</p>
                <button onClick={() => setCurrentPage('DASHBOARD')} className="px-6 py-2 bg-red-600 text-white rounded-lg font-bold">Voltar ao Início</button>
            </div>
        );
    }
  };

  if (!isUserInitialized) {
      return (
          <div className="h-screen w-full flex items-center justify-center bg-gray-50 dark:bg-gray-950">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
          </div>
      );
  }

  if (hasError) {
      return (
          <div className="h-screen w-full flex flex-col items-center justify-center bg-white p-6 text-center">
              <ExclamationTriangleIcon className="w-20 h-20 text-red-500 mb-6" />
              <h1 className="text-2xl font-black text-gray-900 mb-2">Falha na Inicialização</h1>
              <p className="text-gray-500 mb-6 max-w-md">O banco de dados local pode estar corrompido ou o navegador bloqueou o acesso.</p>
              <button onClick={() => dataService.resetDatabase()} className="px-8 py-3 bg-red-600 text-white rounded-xl font-bold shadow-lg">Resetar Sistema (Limpar Tudo)</button>
          </div>
      );
  }

  return (
    <div className="flex h-screen bg-gray-50 dark:bg-gray-950 transition-colors duration-300">
      <Sidebar 
        currentPage={currentPage} 
        setCurrentPage={handleSetCurrentPage} 
        isSidebarOpen={isSidebarOpen} 
        setSidebarOpen={setSidebarOpen} 
        currentUser={currentUser} 
        userPermissions={userPermissions}
        onLogout={handleLogout}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <Header title="Orner Solar" onMenuClick={() => setSidebarOpen(!isSidebarOpen)} />
        <main className="flex-1 overflow-x-hidden overflow-y-auto p-4 md:p-8">
          {renderPage()}
        </main>
      </div>
    </div>
  );
};

export default App;
